script:
test("work submitted exactly at the deadline keeps its raw score", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200000 }), { periodsLate: 0, deduction: 0, score: 45 });
});

test("work submitted one millisecond early is not penalised", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50.0, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067199999.0 }), { periodsLate: 0, deduction: 0, score: 45 });
});

test("one hour late is one started period and deducts 10 percent of the maximum", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704070800000 }), { periodsLate: 1, deduction: 5, score: 40 });
});

test("one millisecond late is one started period", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200001 }), { periodsLate: 1, deduction: 5, score: 40 });
});

test("exactly 24 hours late is one period not two", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 80, rawScore: 70, deadline: 1706659200000, submittedAt: 1706745600000 }), { periodsLate: 1, deduction: 8, score: 62 });
});

test("one millisecond under 24 hours is still one started period", function () {
  assert.equal(code.countLatePeriods({ deadline: 1706659200000, submittedAt: 1706745599999 }), 1);
});

test("one millisecond over 24 hours starts a second period", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 80, rawScore: 70, deadline: 1706659200000, submittedAt: 1706745600001 }), { periodsLate: 2, deduction: 16, score: 54 });
});

test("49 hours late is three periods and deducts 15 from a maximum of 50", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1703980800000, submittedAt: 1704157200000 }), { periodsLate: 3, deduction: 15, score: 30 });
});

test("exactly 48 hours spanning a leap day is two periods not one", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1709078400000, submittedAt: 1709251200000 }), { periodsLate: 2, deduction: 10, score: 35 });
});

test("exactly 120 hours late is five periods and deducts 25", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1709164800000, submittedAt: 1709596800000 }), { periodsLate: 5, deduction: 25, score: 20 });
});

test("one millisecond under 120 hours is still five periods", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 40, rawScore: 33, deadline: 1709164800000, submittedAt: 1709596799999 }), { periodsLate: 5, deduction: 20, score: 13 });
});

test("120 hours and one minute late is six periods and scores 0", function () {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1709164800000, submittedAt: 1709596860000 });
  assert.equal(result.periodsLate, 6);
  assert.equal(result.score, 0);
});

test("one millisecond over 120 hours is six periods and scores 0", function () {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1709164800000, submittedAt: 1709596800001 });
  assert.equal(result.periodsLate, 6);
  assert.equal(result.score, 0);
});

test("a penalty larger than the raw score floors the score at 0 and still reports the full deduction", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 10, deadline: 1703980800000, submittedAt: 1704157200000 }), { periodsLate: 3, deduction: 15, score: 0 });
});

test("a raw score of 0 stays 0 after a one period deduction", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 30, rawScore: 0, deadline: 1704067200000, submittedAt: 1704070800000 }), { periodsLate: 1, deduction: 3, score: 0 });
});

test("an unknown field throws an error naming that field", function () {
  assert.throws(function () {
    code.applyLatePenalty({ maxPoints: 50, rawScore: 45, bonus: 1, deadline: 1704067200000, submittedAt: 1704067200000 });
  }, /unknown field: bonus/);
});
